t":93},{"hour":2,"elecDemand":86,"heatDemand":190,"coolDemand":17,"engineElec":0,"recoveredHeat":0,"chillerCool":0,"gridImport":91},{"hour":3,"elecDemand":85,"heatDemand":197,"coolDemand":17,"engineElec":0,"recoveredHeat":0,"chillerCool":0,"gridImport":90},{"hour":4,"elecDemand":86,"heatDemand":219,"coolDemand":17,"engineElec":0,"recoveredHeat":0,"chillerCool":0,"gridImport":91},{"hour":5,"elecDemand":91,"heatDemand":266,"coolDemand":19,"engineElec":0,"recoveredHeat":0,"chillerCool":0,"gridImport":96},{"hour":6,"elecDemand":101,"heatDemand":330,"coolDemand":19,"engineElec":106,"recoveredHeat":120,"chillerCool":0,"gridImport":0},{"hour":7,"elecDemand":117,"heatDemand":379,"coolDemand":22,"engineElec":123,"recoveredHeat":139,"chillerCool":0,"gridImport":0},{"hour":8,"elecDemand":128,"heatDemand":375,"coolDemand":26,"engineElec":136,"recoveredHeat":153,"chillerCool":0,"gridImport":0},{"hour":9,"elecDemand":127,"heatDemand":322,"coolDemand":36,"engineElec":137,"recoveredHeat":155,"chillerCool":0,"gridImport":0},{"hour":10,"elecDemand":122,"heatDemand":263,"coolDemand":49,"engineElec":136,"recoveredHeat":154,"chillerCool":0,"gridImport":0},{"hour":11,"elecDemand":125,"heatDemand":234,"coolDemand":68,"engineElec":145,"recoveredHeat":164,"chillerCool":0,"gridImport":0},{"hour":12,"elecDemand":132,"heatDemand":232,"coolDemand":86,"engineElec":157,"recoveredHeat":178,"chillerCool":0,"gridImport":0},{"hour":13,"elecDemand":134,"heatDemand":224,"coolDemand":104,"engineElec":164,"recoveredHeat":185,"chillerCool":0,"gridImport":0},{"hour":14,"elecDemand":128,"heatDemand":206,"coolDemand":114,"engineElec":161,"recoveredHeat":182,"chillerCool":0,"gridImport":0},{"hour":15,"elecDemand":127,"heatDemand":197,"coolDemand":114,"engineElec":159,"recoveredHeat":180,"chillerCool":0,"gridImport":0},{"hour":16,"elecDemand":138,"heatDemand":214,"coolDemand":104,"engineElec":168,"recoveredHeat":190,"chillerCool":0,"gridImport":0},{"hour":17,"elecDemand":161,"heatDemand":253,"coolDemand":86,"engineElec":186,"recoveredHeat":210,"chillerCool":0,"gridImport":0},{"hour":18,"elecDemand":184,"heatDemand":300,"coolDemand":68,"engineElec":200,"recoveredHeat":226,"chillerCool":0,"gridImport":4},{"hour":19,"elecDemand":194,"heatDemand":331,"coolDemand":49,"engineElec":200,"recoveredHeat":226,"chillerCool":0,"gridImport":8},{"hour":20,"elecDemand":183,"heatDemand":332,"coolDemand":36,"engineElec":193,"recoveredHeat":219,"chillerCool":0,"gridImport":0},{"hour":21,"elecDemand":157,"heatDemand":305,"coolDemand":26,"engineElec":164,"recoveredHeat":186,"chillerCool":0,"gridImport":0},{"hour":22,"elecDemand":128,"heatDemand":260,"coolDemand":22,"engineElec":134,"recoveredHeat":152,"chillerCool":0,"gridImport":0},{"hour":23,"elecDemand":107,"heatDemand":222,"coolDemand":19,"engineElec":112,"recoveredHeat":127,"chillerCool":0,"gridImport":0}]},"assumptions":[{"name":"Natural gas price (per kWh LHV, before VAT)","unfavourable":0.09,"central":0.068,"favourable":0.068,"unit":"TND/kWh","source":"STEG MP1 71.1 + 0.25 FTE mill/thermie (in force since 1 May 2022, via FIPA Jan 2024 https://investintunisia.tn/wp-content/uploads/2024/01/Couts-des-facteurs-FIPA-Janvier-2024.pdf) = 0.061 TND/kWh HHV = 0.068 LHV. Unfavourable: +32% for a subsidy reform (ESTIMATE)"},{"name":"Engine electrical efficiency (LHV)","unfavourable":0.35,"central":0.38,"favourable":0.4,"unit":"fraction","source":"DOE CHP reciprocating engines fact sheet: 27.7% (35 kW) to 40.6% (4.5 MW) HHV; 400-600 kWe class ~35-40% LHV https://betterbuildingssolutioncenter.energy.gov/sites/default/files/attachments/CHP_Reciprocating_Engines.pdf (ESTIMATE within range)"},{"name":"Engine useful heat recovery efficiency (LHV, hot water ~90 °C)","unfavourable":0.42,"central":0.43,"favourable":0.45,"unit":"fraction","source":"Chosen so total efficiency is 0.77-0.85, the 75-85% range in DOE https://betterbuildingssolutioncenter.energy.gov/sites/default/files/attachments/CHP_Reciprocating_Engines.pdf and docs research §1. v1 used 1.67 kWth/kWe (total 0.96), physically too high"},{"name":"Installed engine plant cost at 500 kWe (incl. balance of plant, gas and grid connection)","unfavourable":9100,"central":7000,"favourable":5000,"unit":"TND/kWe","source":"DOE installed cost $3,150/kW at 500 kW (2020 USD) x 2.89 TND/USD = 9,100 (unfavourable, US labour). Central and favourable assume lower Tunisian installation cost: ESTIMATE until an installer quote. v1 used 2,000 (fleet average of mostly multi-MW plants)"},{"name":"Engine cost scaling with size, (kWe / 500) ^ exponent","unfavourable":-0.12,"central":-0.12,"favourable":-0.12,"unit":"-","source":"Fitted to the DOE curve: $3,700/kW at 100 kW, $3,150 at 500 kW, $2,800 at 1 MW https://betterbuildingssolutioncenter.energy.gov/sites/default/files/attachments/CHP_Reciprocating_Engines.pdf"},{"name":"Absorption chiller installed cost, with cooling tower","unfavourable":4500,"central":3000,"favourable":2000,"unit":"TND/kWc","source":"DOE single-effect $1,800-6,000 per RT = 1,480-4,930 TND/kWc, higher for small units https://www.energy.gov/sites/default/files/2017/06/f35/CHP-Absorption%20Chiller-compliant.pdf. ESTIMATE within range"},{"name":"Engine maintenance including overhauls","unfavourable":0.058,"central":0.04,"favourable":0.03,"unit":"TND/kWh produced","source":"DOE non-fuel O&M 2.0 US cents/kWh at 500 kW = 0.058 TND (unfavourable) https://betterbuildingssolutioncenter.energy.gov/sites/default/files/attachments/CHP_Reciprocating_Engines.pdf; lower Tunisian labour cost for central/favourable is an ESTIMATE"},{"name":"Absorption chiller COP (single-effect)","unfavourable":0.65,"central":0.7,"favourable":0.75,"unit":"kWc/kWth","source":"DOE 0.70-0.79 at rating; 0.65 allows for 40 °C+ heat rejection in Djerba summers https://www.energy.gov/sites/default/files/2017/06/f35/CHP-Absorption%20Chiller-compliant.pdf"},{"name":"Absorption chiller parasitic electricity (pumps, cooling tower fans)","unfavourable":0.04,"central":0.03,"favourable":0.02,"unit":"kWe per kWc","source":"ESTIMATE: typical cooling-tower fan and pump loads; a single-effect chiller rejects ~2.4 kW of heat per kWc"},{"name":"Existing electric chiller seasonal COP (baseline)","unfavourable":4.5,"central":3.5,"favourable":3,"unit":"kWc/kWe","source":"ESTIMATE: older air-cooled chillers and splits ~3, newer units 3.5-4.5, efficient water-cooled 5-6. v1 used 3.0 (flattering)"},{"name":"Gas boiler efficiency (baseline, LHV)","unfavourable":0.92,"central":0.92,"favourable":0.92,"unit":"fraction","source":"EU reference efficiency for hot water, Ref_Hη = 92%"},{"name":"Grid CO2 intensity","unfavourable":0.4,"central":0.48,"favourable":0.48,"unit":"kg CO2/kWh","source":"LowCarbonPower, Tunisia 467 g (2024) to 483 g (2025) https://lowcarbonpower.org/region/Tunisia. Unfavourable 0.40: grid getting cleaner over plant life (ESTIMATE)"},{"name":"Natural gas CO2 factor","unfavourable":0.202,"central":0.202,"favourable":0.202,"unit":"kg CO2/kWh LHV","source":"IPCC default 56.1 t CO2/TJ"},{"name":"Summer occupancy (150 days, mid-May to mid-October)","unfavourable":0.8,"central":0.85,"favourable":0.9,"unit":"fraction","source":"ONTT: Djerba-Zarzis 64.4% Jan-Aug 2026 (La Presse, 9 Oct 2026); 80% late June 2024, 90% one day in July 2025 (regional tourism delegate). ESTIMATE for the season average"},{"name":"Winter and shoulder occupancy (215 days)","unfavourable":0.4,"central":0.48,"favourable":0.55,"unit":"fraction","source":"Chosen so the year averages ~63% at central, consistent with ONTT 64.4% Jan-Aug 2026. ESTIMATE"},{"name":"Count the STEG demand-charge saving (11 TND/kW/month)","unfavourable":0,"central":0,"favourable":1,"unit":"yes=1","source":"STEG MV time-of-use redevance de puissance 11,000 mill/kW/month on Pr = 0.4 P winter peak + 0.3 P summer peak + 0.2 P day + 0.1 P evening (FIPA https://investintunisia.tn/wp-content/uploads/2024/01/Couts-des-facteurs-FIPA-Janvier-2024.pdf; Wattnow guide). Only favourable: one engine trip at peak loses it"}]}'::jsonb, '2.0.0', 'demo-djerba', '2026-11-20T09:00:00.000Z', '2026-11-20T09:00:00.000Z')
