insert into public.lead_notes (lead_id, author_id, body, created_at) values
  ('L-1047', 'a0000000-0000-4000-8000-000000000001', 'First call with Rania (technical director). Open all year, 500 rooms, heated indoor + outdoor pool, gas already on site for the kitchens and boilers. Two old 400 kW screw chillers due for replacement in 2028. Very interested in the CHP-only first step. Wants a study price before the board meets on 10 December.', '2026-11-17T11:20:00.000Z'),
  ('L-1047', 'a0000000-0000-4000-8000-000000000002', 'Re-ran the engine with their real winter occupancy (55%). Central payback moves from 8 to about 7.5 years. Worth asking for the heated indoor pool hours too: they run it 7:00 to 22:00 all winter.', '2026-11-18T10:05:00.000Z'),
  ('L-1047', 'a0000000-0000-4000-8000-000000000001', 'Rania sent all 12 STEG bills (Nov 2025 to Oct 2026). Average 0.231 TND/kWh before VAT, peak demand 1.1 MW in August. Uploaded under Files.', '2026-11-21T16:40:00.000Z'),
  ('L-1046', 'a0000000-0000-4000-8000-000000000003', 'First call with Walid. Heated pool, 300 rooms. Asked for 12 months of STEG bills.', '2026-11-14T11:00:00.000Z'),
  ('L-1045', 'a0000000-0000-4000-8000-000000000002', 'First call with Amel. Heated pool, 380 rooms. Asked for 12 months of STEG bills.', '2026-11-13T11:00:00.000Z'),
  ('L-1044', 'a0000000-0000-4000-8000-000000000001', 'First call with Nizar. Heated pool, 450 rooms. Asked for 12 months of STEG bills.', '2026-11-10T11:00:00.000Z'),
  ('L-1043', 'a0000000-0000-4000-8000-000000000001', 'First call with Sonia. Heated pool, 600 rooms. Asked for 12 months of STEG bills.', '2026-10-31T11:00:00.000Z'),
  ('L-1043', 'a0000000-0000-4000-8000-000000000001', 'Bills received. Quoted the study at 12,500 TND before VAT (two installer quotes included).', '2026-11-07T15:25:00.000Z'),
  ('L-1042', 'a0000000-0000-4000-8000-000000000004', 'First call with Hichem. Heated pool, 220 rooms. Asked for 12 months of STEG bills.', '2026-10-26T11:00:00.000Z'),
  ('L-1042', 'a0000000-0000-4000-8000-000000000004', 'Bills received. Quoted the study at 7,800 TND before VAT (two installer quotes included).', '2026-11-02T15:25:00.000Z'),
  ('L-1041', 'a0000000-0000-4000-8000-000000000002', 'First call with Olfa. Heated pool, 520 rooms. Asked for 12 months of STEG bills.', '2026-10-22T11:00:00.000Z'),
  ('L-1041', 'a0000000-0000-4000-8000-000000000002', 'Bills received. Quoted the study at 11,000 TND before VAT (two installer quotes included).', '2026-10-29T15:25:00.000Z'),
  ('L-1040', 'a0000000-0000-4000-8000-000000000003', 'First call with Anis. Heated pool, 700 rooms. Asked for 12 months of STEG bills.', '2026-10-17T11:00:00.000Z'),
  ('L-1040', 'a0000000-0000-4000-8000-000000000003', 'Bills received. Quoted the study at 14,000 TND before VAT (two installer quotes included).', '2026-10-24T15:25:00.000Z'),
  ('L-1039', 'a0000000-0000-4000-8000-000000000001', 'First call with Fatma. Heated pool, 480 rooms. Asked for 12 months of STEG bills.', '2026-10-02T11:00:00.000Z'),
  ('L-1039', 'a0000000-0000-4000-8000-000000000001', 'Bills received. Quoted the study at 12,000 TND before VAT (two installer quotes included).', '2026-10-09T15:25:00.000Z'),
  ('L-1038', 'a0000000-0000-4000-8000-000000000003', 'First call with Mehdi. Heated pool, 260 rooms. Asked for 12 months of STEG bills.', '2026-09-24T11:00:00.000Z'),
  ('L-1038', 'a0000000-0000-4000-8000-000000000003', 'Bills received. Quoted the study at 8,500 TND before VAT (two installer quotes included).', '2026-10-01T15:25:00.000Z'),
  ('L-1037', 'a0000000-0000-4000-8000-000000000002', 'First call with Nadia. 90 rooms. Asked for 12 months of STEG bills.', '2026-09-20T11:00:00.000Z'),
  ('L-1037', 'a0000000-0000-4000-8000-000000000002', 'Weak fit (about 2,400 full-load hours). We advised rooftop PV and efficient chillers instead.', '2026-09-24T17:15:00.000Z'),
  ('L-1036', 'a0000000-0000-4000-8000-000000000004', 'First call with Bilel. Heated pool, 320 rooms. Asked for 12 months of STEG bills.', '2026-09-12T11:00:00.000Z'),
  ('L-1036', 'a0000000-0000-4000-8000-000000000004', 'Closed November to March, so the engine would idle half the year. Chose solar thermal for the pool.', '2026-09-16T17:15:00.000Z')
